create or replace function public.validate_commercial_catalog() returns trigger language plpgsql security invoker set search_path='' as $$
declare
 catalog jsonb := '[{"id":"landing-page-basica","category":"Sites","name":"Landing page básica","price_cents":40000,"deadline":"3 dias úteis","scope":"Uma página com até 4 blocos e botão de contato.","monthly":false,"website":true},{"id":"landing-page-profissional","category":"Sites","name":"Landing page profissional","price_cents":60000,"deadline":"5 dias úteis","scope":"Uma página com até 7 blocos, formulário e WhatsApp.","monthly":false,"website":true},{"id":"landing-page-premium","category":"Sites","name":"Landing page premium","price_cents":80000,"deadline":"7 dias úteis","scope":"Até 10 blocos, animações e medição básica de ações.","monthly":false,"website":true},{"id":"portfolio-profissional","category":"Sites","name":"Portfólio profissional","price_cents":60000,"deadline":"5 dias úteis","scope":"Até 4 páginas e 10 projetos.","monthly":false,"website":true},{"id":"site-institucional","category":"Sites","name":"Site institucional","price_cents":90000,"deadline":"7 dias úteis","scope":"Até 3 páginas, contato, mapa e redes sociais.","monthly":false,"website":true},{"id":"site-empresarial-completo","category":"Sites","name":"Site empresarial completo","price_cents":140000,"deadline":"10 dias úteis","scope":"Até 5 páginas, formulário e SEO básico.","monthly":false,"website":true},{"id":"site-premium-personalizado","category":"Sites","name":"Site premium personalizado","price_cents":180000,"deadline":"15 dias úteis","scope":"Até 7 páginas e animações leves.","monthly":false,"website":true},{"id":"site-com-painel-administrativo","category":"Sites","name":"Site com painel administrativo","price_cents":200000,"deadline":"15 dias úteis","scope":"Até 5 páginas e edição de uma categoria de conteúdo.","monthly":false,"website":true},{"id":"reformulacao-de-site","category":"Sites","name":"Reformulação de site","price_cents":70000,"deadline":"7 dias úteis","scope":"Reformulação de até 3 páginas.","monthly":false,"website":true},{"id":"cardapio-digital-em-pdf","category":"Cardápios","name":"Cardápio digital em PDF","price_cents":25000,"deadline":"3 dias úteis","scope":"Até 4 páginas e 40 itens.","monthly":false,"website":false},{"id":"cardapio-digital-profissional","category":"Cardápios","name":"Cardápio digital profissional","price_cents":45000,"deadline":"5 dias úteis","scope":"Até 50 itens, categorias e QR Code.","monthly":false,"website":true},{"id":"site-institucional-com-cardapio","category":"Cardápios","name":"Site institucional com cardápio","price_cents":100000,"deadline":"8 dias úteis","scope":"Até 3 páginas e cardápio de 50 itens.","monthly":false,"website":true},{"id":"site-completo-com-sistema-de-pedidos","category":"Cardápios","name":"Site completo com sistema de pedidos","price_cents":200000,"deadline":"12 dias úteis","scope":"Até 50 itens, carrinho e pedido via WhatsApp.","monthly":false,"website":true},{"id":"catalogo-digital","category":"Lojas virtuais","name":"Catálogo digital","price_cents":50000,"deadline":"5 dias úteis","scope":"Até 30 produtos, sem checkout.","monthly":false,"website":true},{"id":"loja-com-pedidos-via-whatsapp","category":"Lojas virtuais","name":"Loja com pedidos via WhatsApp","price_cents":100000,"deadline":"8 dias úteis","scope":"Até 40 produtos, carrinho e pedido via WhatsApp.","monthly":false,"website":true},{"id":"loja-virtual-completa","category":"Lojas virtuais","name":"Loja virtual completa","price_cents":200000,"deadline":"15 dias úteis","scope":"Até 50 produtos, checkout e painel padrão.","monthly":false,"website":true},{"id":"e-commerce-avancado","category":"Lojas virtuais","name":"E-commerce avançado","price_cents":300000,"deadline":"20 dias úteis","scope":"Até 100 produtos, 1 integração e painel padrão.","monthly":false,"website":true},{"id":"scripts-personalizados","category":"Sistemas e automações","name":"Scripts personalizados","price_cents":25000,"deadline":"3 dias úteis","scope":"Um script para uma tarefa.","monthly":false,"website":false},{"id":"bots-personalizados","category":"Sistemas e automações","name":"Bots personalizados","price_cents":45000,"deadline":"5 dias úteis","scope":"Um bot com até 5 comandos.","monthly":false,"website":false},{"id":"automacao-de-processos","category":"Sistemas e automações","name":"Automação de processos","price_cents":60000,"deadline":"7 dias úteis","scope":"Um fluxo com até 3 etapas e 1 serviço externo.","monthly":false,"website":false},{"id":"integracao-de-sistemas-e-apis","category":"Sistemas e automações","name":"Integração de sistemas e APIs","price_cents":70000,"deadline":"8 dias úteis","scope":"2 serviços, até 3 operações.","monthly":false,"website":false},{"id":"painel-administrativo","category":"Sistemas e automações","name":"Painel administrativo","price_cents":120000,"deadline":"10 dias úteis","scope":"Até 3 telas e gestão de um tipo de registro.","monthly":false,"website":false},{"id":"sistema-empresarial-inicial","category":"Sistemas e automações","name":"Sistema empresarial inicial","price_cents":350000,"deadline":"25 dias úteis","scope":"Login, até 3 módulos simples e 1 perfil.","monthly":false,"website":false},{"id":"integracao-com-inteligencia-artificial","category":"Sistemas e automações","name":"Integração com inteligência artificial","price_cents":120000,"deadline":"10 dias úteis","scope":"Um recurso de IA via API em sistema existente.","monthly":false,"website":false},{"id":"configuracao-de-campanhas","category":"Tráfego pago","name":"Configuração de campanhas","price_cents":30000,"deadline":"3 dias úteis","scope":"Uma plataforma e uma campanha.","monthly":false,"website":false},{"id":"meta-ads","category":"Tráfego pago","name":"Meta Ads","price_cents":60000,"deadline":"30 dias corridos","scope":"Até 2 campanhas e relatório mensal.","monthly":true,"website":false},{"id":"google-ads","category":"Tráfego pago","name":"Google Ads","price_cents":70000,"deadline":"30 dias corridos","scope":"Até 2 campanhas e relatório mensal.","monthly":true,"website":false},{"id":"meta-ads-google-ads","category":"Tráfego pago","name":"Meta Ads + Google Ads","price_cents":100000,"deadline":"30 dias corridos","scope":"Até 2 campanhas por plataforma.","monthly":true,"website":false},{"id":"gestao-avancada-de-trafego","category":"Tráfego pago","name":"Gestão avançada de tráfego","price_cents":150000,"deadline":"30 dias corridos","scope":"Até 6 campanhas, testes e acompanhamento semanal.","monthly":true,"website":false},{"id":"manutencao-mensal-opcional","category":"Suporte","name":"Manutenção mensal opcional","price_cents":15000,"deadline":"Mensal","scope":"Até 1 hora de pequenos ajustes.","monthly":true,"website":false},{"id":"atualizacao-mensal-de-cardapio","category":"Suporte","name":"Atualização mensal de cardápio","price_cents":8000,"deadline":"Mensal","scope":"Até 15 alterações de itens ou preços.","monthly":true,"website":false},{"id":"pagina-adicional","category":"Suporte","name":"Página adicional","price_cents":20000,"deadline":"3 dias úteis","scope":"Uma página de até 5 seções.","monthly":false,"website":false},{"id":"correcoes-e-melhorias","category":"Suporte","name":"Correções e melhorias","price_cents":25000,"deadline":"3 dias úteis","scope":"Um chamado de até 2 horas.","monthly":false,"website":false},{"id":"otimizacao-para-buscas-seo","category":"Suporte","name":"Otimização para buscas (SEO)","price_cents":35000,"deadline":"5 dias úteis","scope":"SEO técnico de até 5 páginas.","monthly":false,"website":false},{"id":"otimizacao-de-desempenho","category":"Suporte","name":"Otimização de desempenho","price_cents":30000,"deadline":"5 dias úteis","scope":"Ajustes em até 5 páginas.","monthly":false,"website":false},{"id":"integracoes-adicionais","category":"Suporte","name":"Integrações adicionais","price_cents":40000,"deadline":"5 dias úteis","scope":"Uma integração simples.","monthly":false,"website":false}]'::jsonb;
 us_catalog constant jsonb := '[{"id":"landing-page-basica","category":"Websites","name":"Basic landing page","price_cents":25000,"deadline":"3 business days","scope":"One page, up to 4 sections and a contact button.","monthly":false,"website":true},{"id":"landing-page-profissional","category":"Websites","name":"Professional landing page","price_cents":40000,"deadline":"5 business days","scope":"One page, up to 7 sections, a form and WhatsApp.","monthly":false,"website":true},{"id":"landing-page-premium","category":"Websites","name":"Premium landing page","price_cents":55000,"deadline":"7 business days","scope":"Up to 10 sections, animations and basic event tracking.","monthly":false,"website":true},{"id":"portfolio-profissional","category":"Websites","name":"Professional portfolio","price_cents":40000,"deadline":"5 business days","scope":"Up to 4 pages and 10 projects.","monthly":false,"website":true},{"id":"site-institucional","category":"Websites","name":"Business website","price_cents":60000,"deadline":"7 business days","scope":"Up to 3 pages, contact, map and social links.","monthly":false,"website":true},{"id":"site-empresarial-completo","category":"Websites","name":"Complete business website","price_cents":90000,"deadline":"10 business days","scope":"Up to 5 pages, a form and basic SEO.","monthly":false,"website":true},{"id":"site-premium-personalizado","category":"Websites","name":"Custom premium website","price_cents":120000,"deadline":"15 business days","scope":"Up to 7 pages and light animations.","monthly":false,"website":true},{"id":"site-com-painel-administrativo","category":"Websites","name":"Website with admin dashboard","price_cents":140000,"deadline":"15 business days","scope":"Up to 5 pages and editing one content category.","monthly":false,"website":true},{"id":"reformulacao-de-site","category":"Websites","name":"Website redesign","price_cents":45000,"deadline":"7 business days","scope":"Redesign of up to 3 pages.","monthly":false,"website":true},{"id":"cardapio-digital-em-pdf","category":"Menus","name":"PDF digital menu","price_cents":15000,"deadline":"3 business days","scope":"Up to 4 pages and 40 items.","monthly":false,"website":false},{"id":"cardapio-digital-profissional","category":"Menus","name":"Professional digital menu","price_cents":30000,"deadline":"5 business days","scope":"Up to 50 items, categories and QR code.","monthly":false,"website":true},{"id":"site-institucional-com-cardapio","category":"Menus","name":"Restaurant website with menu","price_cents":70000,"deadline":"8 business days","scope":"Up to 3 pages and a 50-item menu.","monthly":false,"website":true},{"id":"site-completo-com-sistema-de-pedidos","category":"Menus","name":"Website with ordering system","price_cents":140000,"deadline":"12 business days","scope":"Up to 50 items, cart and orders through WhatsApp.","monthly":false,"website":true},{"id":"catalogo-digital","category":"Online stores","name":"Digital product catalog","price_cents":35000,"deadline":"5 business days","scope":"Up to 30 products, no checkout.","monthly":false,"website":true},{"id":"loja-com-pedidos-via-whatsapp","category":"Online stores","name":"Store with WhatsApp ordering","price_cents":70000,"deadline":"8 business days","scope":"Up to 40 products, cart and orders through WhatsApp.","monthly":false,"website":true},{"id":"loja-virtual-completa","category":"Online stores","name":"Complete online store","price_cents":140000,"deadline":"15 business days","scope":"Up to 50 products, standard checkout and dashboard.","monthly":false,"website":true},{"id":"e-commerce-avancado","category":"Online stores","name":"Advanced e-commerce","price_cents":220000,"deadline":"20 business days","scope":"Up to 100 products, one integration and a standard dashboard.","monthly":false,"website":true},{"id":"scripts-personalizados","category":"Systems & automation","name":"Custom scripts","price_cents":15000,"deadline":"3 business days","scope":"One script for one task.","monthly":false,"website":false},{"id":"bots-personalizados","category":"Systems & automation","name":"Custom bots","price_cents":30000,"deadline":"5 business days","scope":"One bot with up to 5 commands.","monthly":false,"website":false},{"id":"automacao-de-processos","category":"Systems & automation","name":"Process automation","price_cents":40000,"deadline":"7 business days","scope":"One workflow, up to 3 steps and one external service.","monthly":false,"website":false},{"id":"integracao-de-sistemas-e-apis","category":"Systems & automation","name":"Systems and API integration","price_cents":50000,"deadline":"8 business days","scope":"Two services and up to 3 operations.","monthly":false,"website":false},{"id":"painel-administrativo","category":"Systems & automation","name":"Admin dashboard","price_cents":85000,"deadline":"10 business days","scope":"Up to 3 screens and management of one record type.","monthly":false,"website":false},{"id":"sistema-empresarial-inicial","category":"Systems & automation","name":"Starter business system","price_cents":250000,"deadline":"25 business days","scope":"Login, up to 3 simple modules and one user role.","monthly":false,"website":false},{"id":"integracao-com-inteligencia-artificial","category":"Systems & automation","name":"AI integration","price_cents":85000,"deadline":"10 business days","scope":"One AI API feature in an existing system.","monthly":false,"website":false},{"id":"configuracao-de-campanhas","category":"Paid ads","name":"Campaign setup","price_cents":20000,"deadline":"3 business days","scope":"One platform and one campaign.","monthly":false,"website":false},{"id":"meta-ads","category":"Paid ads","name":"Meta Ads management","price_cents":40000,"deadline":"30 calendar days","scope":"Up to 2 campaigns and a monthly report.","monthly":true,"website":false},{"id":"google-ads","category":"Paid ads","name":"Google Ads management","price_cents":45000,"deadline":"30 calendar days","scope":"Up to 2 campaigns and a monthly report.","monthly":true,"website":false},{"id":"meta-ads-google-ads","category":"Paid ads","name":"Meta Ads + Google Ads","price_cents":70000,"deadline":"30 calendar days","scope":"Up to 2 campaigns per platform.","monthly":true,"website":false},{"id":"gestao-avancada-de-trafego","category":"Paid ads","name":"Advanced ads management","price_cents":100000,"deadline":"30 calendar days","scope":"Up to 6 campaigns, testing and weekly monitoring.","monthly":true,"website":false},{"id":"manutencao-mensal-opcional","category":"Support","name":"Optional monthly maintenance","price_cents":9900,"deadline":"Monthly","scope":"Up to one hour of minor changes per month.","monthly":true,"website":false},{"id":"atualizacao-mensal-de-cardapio","category":"Support","name":"Monthly menu updates","price_cents":5000,"deadline":"Monthly","scope":"Up to 15 item or price updates.","monthly":true,"website":false},{"id":"pagina-adicional","category":"Support","name":"Additional page","price_cents":12500,"deadline":"3 business days","scope":"One page with up to 5 sections.","monthly":false,"website":false},{"id":"correcoes-e-melhorias","category":"Support","name":"Fixes and improvements","price_cents":17500,"deadline":"3 business days","scope":"One support request, up to 2 hours.","monthly":false,"website":false},{"id":"otimizacao-para-buscas-seo","category":"Support","name":"Search optimization (SEO)","price_cents":25000,"deadline":"5 business days","scope":"Technical SEO for up to 5 pages.","monthly":false,"website":false},{"id":"otimizacao-de-desempenho","category":"Support","name":"Performance optimization","price_cents":20000,"deadline":"5 business days","scope":"Improvements for up to 5 pages.","monthly":false,"website":false},{"id":"integracoes-adicionais","category":"Support","name":"Additional integrations","price_cents":27500,"deadline":"5 business days","scope":"One simple integration.","monthly":false,"website":false}]'::jsonb;
 choice jsonb; offer jsonb; choices jsonb; prefs jsonb := '{}'::jsonb; feat jsonb; feat_seen text[] := '{}'; complexity text; timeline text; features jsonb := '[]'::jsonb; selection jsonb := '[]'::jsonb; seen text[] := '{}';
 infra jsonb; infrastructure jsonb := null; ext jsonb; ext_seen text[] := '{}'; host_choice text; domain_choice text;
 selected_id text; maint text; base int; extra int; once_total int := 0; month_total int := 0; has_site boolean := false;
begin
 if new.market='US' then catalog:=us_catalog; end if;
 if new.catalog_request is null then
  if new.service='Catálogo comercial' then raise exception 'Catalog choices required' using errcode='23514'; end if;
  return new;
 end if;
 if jsonb_typeof(new.catalog_request)='object' then
  choices:=new.catalog_request->'items'; prefs:=coalesce(new.catalog_request->'preferences','{}'::jsonb);
 else choices:=new.catalog_request;
 end if;
 if jsonb_typeof(prefs)<>'object' then raise exception 'Invalid project preferences' using errcode='23514'; end if;
 complexity:=nullif(prefs->>'complexity',''); timeline:=nullif(prefs->>'timeline','');
 if complexity is not null and not(complexity=any(array['Não sei / preciso de orientação','Simples','Intermediário','Avançado'])) then raise exception 'Invalid complexity' using errcode='23514'; end if;
 if timeline is not null and not(timeline=any(array['Flexível','Prazo normal','Urgente'])) then raise exception 'Invalid timeline' using errcode='23514'; end if;
 if prefs ? 'features' then
  if jsonb_typeof(prefs->'features')<>'array' then raise exception 'Invalid features' using errcode='23514'; end if;
  if jsonb_array_length(prefs->'features')>9 then raise exception 'Too many features' using errcode='23514'; end if;
  for feat in select value from jsonb_array_elements(prefs->'features') loop
   if jsonb_typeof(feat)<>'string' or not((feat#>>'{}')=any(array['Painel administrativo','Pagamentos online','Mais de um idioma','Login de usuários','Integração com sistemas/API','Identidade visual do site','WhatsApp','Formulário de contato','SEO'])) or (feat#>>'{}')=any(feat_seen) then raise exception 'Invalid feature' using errcode='23514'; end if;
   feat_seen:=array_append(feat_seen,feat#>>'{}'); features:=features||jsonb_build_array(feat);
  end loop;
 end if;
 if choices is null or jsonb_typeof(choices)<>'array' then raise exception 'Invalid catalog selection' using errcode='23514'; end if;
 if jsonb_array_length(choices) not between 1 and jsonb_array_length(catalog) then raise exception 'Invalid selection count' using errcode='23514'; end if;
 for choice in select value from jsonb_array_elements(choices) loop
  selected_id:=choice->>'id'; maint:=choice->>'maintenance';
  if selected_id is null or selected_id=any(seen) then raise exception 'Invalid or duplicate service' using errcode='23514'; end if;
  select value into offer from jsonb_array_elements(catalog) where value->>'id'=selected_id;
  if offer is null then raise exception 'Unknown catalog service' using errcode='23514'; end if;
  seen:=array_append(seen,selected_id);
  if (offer->>'website')::boolean then
   has_site:=true;
   if maint is null or maint not in ('yes','no') then raise exception 'Choose monthly maintenance for each website' using errcode='23514'; end if;
  elsif maint is not null then raise exception 'Invalid maintenance selection' using errcode='23514'; end if;
  base:=(offer->>'price_cents')::int; extra:=case when maint='yes' then case when new.market='US' then 9900 else 15000 end else 0 end;
  if (offer->>'monthly')::boolean then month_total:=month_total+base; else once_total:=once_total+base; end if;
  month_total:=month_total+extra;
  selection:=selection||jsonb_build_array(offer||jsonb_build_object('maintenance',maint,'maintenance_cents',extra));
 end loop;
 if has_site and 'manutencao-mensal-opcional'=any(seen) then raise exception 'Use the per-site maintenance choice' using errcode='23514'; end if;
 -- Optional for compatibility with the existing production application.
 if prefs ? 'infrastructure' then
  infra:=prefs->'infrastructure';
  if jsonb_typeof(infra) is distinct from 'object' or infra->'acknowledged' is distinct from 'true'::jsonb then raise exception 'External costs acknowledgement required' using errcode='23514'; end if;
  host_choice:=infra->>'hosting'; domain_choice:=infra->>'domain';
  if host_choice is null or host_choice not in ('existing','self','assisted','undecided','not_applicable') or domain_choice is null or domain_choice not in ('existing','new','subdomain','undecided','not_applicable') or (has_site and (host_choice='not_applicable' or domain_choice='not_applicable')) then raise exception 'Invalid infrastructure choices' using errcode='23514'; end if;
  if jsonb_typeof(infra->'extras') is distinct from 'array' then raise exception 'Invalid external services' using errcode='23514'; end if;
  if jsonb_array_length(infra->'extras')>5 then raise exception 'Too many external services' using errcode='23514'; end if;
  for ext in select value from jsonb_array_elements(infra->'extras') loop
   if jsonb_typeof(ext)<>'string' or (ext#>>'{}') not in ('email','database','api','licenses','ads') or (ext#>>'{}')=any(ext_seen) then raise exception 'Invalid or duplicate external service' using errcode='23514'; end if;
   ext_seen:=array_append(ext_seen,ext#>>'{}');
  end loop;
  infrastructure:=jsonb_build_object('hosting',host_choice,'domain',domain_choice,'extras',to_jsonb(ext_seen),'acknowledged',true);
 end if;
 new.catalog_request:=jsonb_build_object('version',1,'market',new.market,'currency',case when new.market='US' then 'USD' else 'BRL' end,'items',selection,'one_time_cents',once_total,'monthly_cents',month_total,'preferences',jsonb_build_object('complexity',complexity,'timeline',timeline,'features',features)||case when infrastructure is null then '{}'::jsonb else jsonb_build_object('infrastructure',infrastructure) end);
 new.service:='Catálogo comercial';
 return new;
end; $$;
create or replace function public.post_catalog_chat_message() returns trigger language plpgsql security invoker set search_path='' as $$
declare item jsonb; en boolean := new.market='US'; prefix text; suffix text; summary text; pref jsonb; infra jsonb; names text[];
pt_features text[]:=array['Painel administrativo','Pagamentos online','Mais de um idioma','Login de usuários','Integração com sistemas/API','Identidade visual do site','WhatsApp','Formulário de contato','SEO'];
en_features text[]:=array['Admin dashboard','Online payments','Multiple languages','User login','Systems/API integration','Website visual identity','WhatsApp','Contact form','SEO'];
pt_complex text[]:=array['Não sei / preciso de orientação','Simples','Intermediário','Avançado'];
en_complex text[]:=array['Not sure / need guidance','Simple','Intermediate','Advanced'];
pt_timeline text[]:=array['Flexível','Prazo normal','Urgente'];
en_timeline text[]:=array['Flexible','Standard timeline','Urgent'];
begin
 if new.catalog_request is null then return new; end if;
 prefix:=case when en then 'USD $' else 'R$ ' end;
 suffix:=case when en then '/month' else '/mês' end;
 summary:=case when en then E'New commercial catalog request (US / USD)\n\n' else E'Novo pedido pelo catálogo comercial (BR / BRL)\n\n' end;
 for item in select value from jsonb_array_elements(new.catalog_request->'items') loop
  summary:=summary||'• '||(item->>'name')||' — '||prefix||case when en then to_char((item->>'price_cents')::numeric/100,'FM999999990.00') else replace(to_char((item->>'price_cents')::numeric/100,'FM999999990.00'),'.',',') end||case when (item->>'monthly')::boolean then suffix else '' end||' · '||(item->>'deadline')||E'\n';
  if (item->>'website')::boolean then summary:=summary||case when en then '  Monthly maintenance: ' else '  Manutenção mensal: ' end||case when item->>'maintenance'='yes' then case when en then 'Yes — USD $99.00/month' else 'Sim — R$ 150,00/mês' end else case when en then 'No — USD $0.00/month' else 'Não — R$ 0,00/mês' end end||E'\n'; end if;
 end loop;
 pref:=new.catalog_request->'preferences';
 if new.budget is not null then summary:=summary||case when en then E'\nBudget range: ' else E'\nFaixa de orçamento: ' end||new.budget||E'\n'; end if;
 if pref->>'complexity' is not null then summary:=summary||case when en then 'Complexity: '||en_complex[array_position(pt_complex,pref->>'complexity')] else 'Complexidade: '||(pref->>'complexity') end||E'\n'; end if;
 if pref->>'timeline' is not null then summary:=summary||case when en then 'Timeline: '||en_timeline[array_position(pt_timeline,pref->>'timeline')] else 'Preferência de prazo: '||(pref->>'timeline') end||E'\n'; end if;
 if jsonb_array_length(coalesce(pref->'features','[]'::jsonb))>0 then
  summary:=summary||case when en then 'Requested features (scope to confirm): ' else 'Recursos desejados (a confirmar no orçamento): ' end||(select string_agg(case when en then en_features[array_position(pt_features,value)] else value end,', ') from jsonb_array_elements_text(pref->'features'))||E'\n';
 end if;
 infra:=pref->'infrastructure';
 if infra is not null then
  summary:=summary||case when en then E'\nHosting: ' else E'\nHospedagem: ' end||
   case infra->>'hosting' when 'existing' then case when en then 'Already have hosting' else 'Já tenho hospedagem' end when 'self' then case when en then 'Will purchase directly' else 'Cliente contratará diretamente' end when 'assisted' then case when en then 'Help choosing and configuring' else 'Ajuda para escolher e configurar' end when 'undecided' then case when en then 'Needs guidance' else 'Preciso de orientação' end else case when en then 'Not applicable' else 'Não se aplica' end end||E'\n'||
   case when en then 'Domain: ' else 'Domínio: ' end||
   case infra->>'domain' when 'existing' then case when en then 'Already have a domain' else 'Já tenho domínio' end when 'new' then case when en then 'Register a custom domain' else 'Registrar domínio próprio' end when 'subdomain' then case when en then 'Subdomain if suitable' else 'Subdomínio se compatível' end when 'undecided' then case when en then 'Needs guidance' else 'Preciso de orientação' end else case when en then 'Not applicable' else 'Não se aplica' end end||E'\n'||
   case when en then 'External services: ' else 'Serviços externos: ' end||
   coalesce((select string_agg(case value when 'email' then case when en then 'Business email' else 'E-mail profissional' end when 'database' then case when en then 'Database/storage' else 'Banco de dados/armazenamento' end when 'api' then case when en then 'Paid APIs' else 'APIs pagas' end when 'licenses' then case when en then 'Licenses' else 'Licenças' end when 'ads' then case when en then 'Ad budget' else 'Verba de anúncios' end end,', ') from jsonb_array_elements_text(infra->'extras')),case when en then 'None selected' else 'Nenhum selecionado' end)||E'\n'||
   case when en then 'Customer acknowledged separate third-party costs. Amounts to be confirmed; not included in maintenance or catalog totals.' else 'Cliente confirmou despesas de terceiros à parte. Valores a combinar; não incluídos na manutenção nem nos totais do catálogo.' end||E'\n';
 end if;
 summary:=summary||case when en then E'\nOne-time total: USD $'||to_char((new.catalog_request->>'one_time_cents')::numeric/100,'FM999999990.00')||E'\nMonthly total: USD $'||to_char((new.catalog_request->>'monthly_cents')::numeric/100,'FM999999990.00')||E'\n\nProject description:\n' else E'\nTotal único: R$ '||replace(to_char((new.catalog_request->>'one_time_cents')::numeric/100,'FM999999990.00'),'.',',')||E'\nTotal mensal: R$ '||replace(to_char((new.catalog_request->>'monthly_cents')::numeric/100,'FM999999990.00'),'.',',')||E'\n\nDescrição do projeto:\n' end||new.message;
 insert into public.commercial_messages(lead_id,sender_id,sender_role,body) values(new.id,new.customer_id,'customer',summary);
 return new;
end; $$;
